BEGIN;SET LOCAL lock_timeout='5s';
DO $guard$ BEGIN
IF md5(pg_get_functiondef('play_claim_daily_supply()'::regprocedure))<>'900f80787810cb762fd78fdf27d02fb5' OR (SELECT proacl::text FROM pg_proc WHERE oid='play_claim_daily_supply()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'OWNER_SUPPLY_SOURCE_OR_ACL_DRIFT';END IF;
IF md5(pg_get_functiondef('play_claim_pass(text)'::regprocedure))<>'06bbb634c0b222b5a5ecef18b9af14b2' OR (SELECT proacl::text FROM pg_proc WHERE oid='play_claim_pass(text)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'OWNER_SUPPLY_SOURCE_OR_ACL_DRIFT';END IF;
IF md5(pg_get_functiondef('private.pass_period_wallet(uuid)'::regprocedure))<>'41d040d6e452c5e0fb0eaf27fe7bf2c0' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.pass_period_wallet(uuid)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'OWNER_SUPPLY_SOURCE_OR_ACL_DRIFT';END IF;
END $guard$;
DO $restore$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $restore$;
DO $restore$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $restore$;
DO $restore$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $restore$;
COMMIT;
